def API_simple_price(vs_currencies, ids=None, names=None, symbols=None, include_tokens=None, include_market_cap=None, include_24hr_vol=None, include_24hr_change=None, include_last_updated_at=None, precision=None, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate inputs
    if not isinstance(vs_currencies, str) or not vs_currencies.strip():
        return _err("VALIDATION_ERROR", "vs_currencies is required and must be a non-empty string")
    for sname, sval in (("ids", ids), ("names", names), ("symbols", symbols)):
        if sval is not None and not isinstance(sval, str):
            return _err("VALIDATION_ERROR", f"{sname} must be a string when provided")
    if include_tokens is not None and include_tokens not in ("top", "all"):
        return _err("VALIDATION_ERROR", "include_tokens must be one of: top, all")
    for bname, bval in (
        ("include_market_cap", include_market_cap),
        ("include_24hr_vol", include_24hr_vol),
        ("include_24hr_change", include_24hr_change),
        ("include_last_updated_at", include_last_updated_at),
    ):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided")
    allowed_precision = {"full"} | {str(i) for i in range(0, 19)}
    if precision is not None and (not isinstance(precision, str) or precision not in allowed_precision):
        return _err("VALIDATION_ERROR", "precision must be 'full' or an integer string between 0 and 18")

    # Parse vs_currencies
    vs_list = [v.strip().lower() for v in vs_currencies.split(",") if v.strip()]
    if not vs_list:
        return _err("VALIDATION_ERROR", "vs_currencies must contain at least 1 currency code")

    # Selector precedence: ids > names > symbols
    def _split_csv(s):
        return [x.strip() for x in s.split(",") if x.strip()]

    selector_kind = None
    selector_values = []
    if ids is not None and ids.strip():
        selector_kind = "ids"
        selector_values = [x.strip().lower() for x in _split_csv(ids)]
    elif names is not None and names.strip():
        selector_kind = "names"
        selector_values = [x.strip().lower() for x in _split_csv(names)]
    elif symbols is not None and symbols.strip():
        selector_kind = "symbols"
        selector_values = [x.strip().lower() for x in _split_csv(symbols)]

    # Load data
    coins = _load("coins.json")
    snaps = _load("coin_market_snapshots.json")
    if not isinstance(coins, list):
        coins = []
    if not isinstance(snaps, list):
        snaps = []

    # Map coins by fields for lookup
    coins_by_cgid = {}
    coins_by_name = {}
    coins_by_symbol = {}
    for c in coins:
        if not isinstance(c, dict):
            continue
        cgid = c.get("coingecko_id")
        if isinstance(cgid, str) and cgid:
            coins_by_cgid[cgid.lower()] = c
        nm = c.get("name")
        if isinstance(nm, str) and nm:
            coins_by_name.setdefault(nm.lower(), []).append(c)
        sym = c.get("symbol")
        if isinstance(sym, str) and sym:
            coins_by_symbol.setdefault(sym.lower(), []).append(c)

    # Determine target coins
    selected_coins = []
    if selector_kind is None:
        # CoinGecko returns empty map if no selector provided
        selected_coins = []
    elif selector_kind == "ids":
        for v in selector_values:
            c = coins_by_cgid.get(v)
            if c:
                selected_coins.append(c)
    elif selector_kind == "names":
        for v in selector_values:
            for c in coins_by_name.get(v, []):
                selected_coins.append(c)
    elif selector_kind == "symbols":
        # include_tokens affects symbols lookups: top vs all
        mode = include_tokens or "top"
        for v in selector_values:
            matches = coins_by_symbol.get(v, [])
            if not matches:
                continue
            if mode == "all":
                selected_coins.extend(matches)
            else:
                # "top": take best-ranked token/coin (lowest market_cap_rank available)
                best = None
                best_rank = None
                for c in matches:
                    rank = None
                    # use snapshot rank if present for any vs_currency, else coin row market_cap_rank if any
                    # Prefer USD snapshot rank
                    coin_pk = c.get("id")
                    if isinstance(coin_pk, str):
                        for s in snaps:
                            if isinstance(s, dict) and s.get("coin_id") == coin_pk and s.get("vs_currency") == "usd":
                                r = s.get("market_cap_rank")
                                if isinstance(r, (int, float)):
                                    rank = r
                                break
                    if rank is None:
                        r = c.get("market_cap_rank")
                        if isinstance(r, (int, float)):
                            rank = r
                    if rank is None:
                        continue
                    if best is None or rank < best_rank:
                        best = c
                        best_rank = rank
                if best is None:
                    # if no ranks at all, just take first deterministically
                    best = matches[0]
                selected_coins.append(best)

    # De-duplicate coins by internal id while preserving order
    seen_internal = set()
    uniq_coins = []
    for c in selected_coins:
        pk = c.get("id")
        if not isinstance(pk, str) or not pk:
            continue
        if pk in seen_internal:
            continue
        seen_internal.add(pk)
        uniq_coins.append(c)
    selected_coins = uniq_coins

    # Index snapshots by (coin_id, vs_currency)
    snap_by_pair = {}
    for s in snaps:
        if not isinstance(s, dict):
            continue
        coin_id = s.get("coin_id")
        vs = s.get("vs_currency")
        if isinstance(coin_id, str) and isinstance(vs, str) and coin_id and vs:
            snap_by_pair[(coin_id, vs.lower())] = s

    # Precision handling
    def _round(v):
        if v is None or not isinstance(v, (int, float)) or isinstance(v, bool):
            return v
        if precision is None or precision == "full":
            return float(v)
        try:
            p = int(precision)
        except Exception:
            return float(v)
        # CoinGecko style: numeric rounding
        return round(float(v), p)

    def _to_unix_seconds(dt_val):
        if dt_val is None:
            return None
        if isinstance(dt_val, (int, float)) and not isinstance(dt_val, bool):
            # Could already be unix seconds
            return int(dt_val)
        if isinstance(dt_val, str):
            s = dt_val.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            try:
                d = datetime.datetime.fromisoformat(s2)
                if d.tzinfo is None:
                    d = d.replace(tzinfo=datetime.timezone.utc)
                return int(d.timestamp())
            except Exception:
                return None
        if isinstance(dt_val, datetime.datetime):
            d = dt_val
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return int(d.timestamp())
        return None

    # Build response map keyed by coin coingecko_id
    out = {}
    for c in selected_coins:
        cgid = c.get("coingecko_id")
        coin_pk = c.get("id")
        if not (isinstance(cgid, str) and cgid and isinstance(coin_pk, str) and coin_pk):
            continue
        coin_key = cgid  # results keyed by coingecko_id per business rules
        coin_obj = {}
        any_currency_written = False
        for vs in vs_list:
            snap = snap_by_pair.get((coin_pk, vs))
            if not snap:
                continue
            price = snap.get("current_price")
            if not isinstance(price, (int, float)) or isinstance(price, bool):
                continue
            coin_obj[vs] = _round(price)
            any_currency_written = True

            if include_market_cap:
                mc = snap.get("market_cap")
                if isinstance(mc, (int, float)) and not isinstance(mc, bool):
                    coin_obj[f"{vs}_market_cap"] = _round(mc)
            if include_24hr_vol:
                tv = snap.get("total_volume")
                if isinstance(tv, (int, float)) and not isinstance(tv, bool):
                    coin_obj[f"{vs}_24h_vol"] = _round(tv)
            if include_24hr_change:
                # CoinGecko simple/price uses percentage when available; fallback to price_change_24h
                pc_pct = snap.get("price_change_percentage_24h")
                if isinstance(pc_pct, (int, float)) and not isinstance(pc_pct, bool):
                    coin_obj[f"{vs}_24h_change"] = _round(pc_pct)
                else:
                    pc = snap.get("price_change_24h")
                    if isinstance(pc, (int, float)) and not isinstance(pc, bool):
                        coin_obj[f"{vs}_24h_change"] = _round(pc)
            if include_last_updated_at:
                lu = snap.get("last_updated")
                ts = _to_unix_seconds(lu)
                if ts is not None:
                    coin_obj["last_updated_at"] = ts

        if any_currency_written:
            out[coin_key] = coin_obj

    # Return map (empty if nothing matched) - normal envelope
    return {
        "data": out,
        "meta": {
            "requested_vs_currencies": vs_list,
            "selector": selector_kind,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def API_coins_list(include_platform=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    status = 200
    try:
        if include_platform is not None and not isinstance(include_platform, bool):
            status = 400
            return _err("VALIDATION_ERROR", "include_platform must be a boolean when provided")

        coins = _load("coins.json")
        out = []
        inc = bool(include_platform)
        for c in coins if isinstance(coins, list) else []:
            if not isinstance(c, dict):
                continue
            cgid = c.get("coingecko_id")
            sym = c.get("symbol")
            name = c.get("name")
            if not isinstance(cgid, str) or not isinstance(sym, str) or not isinstance(name, str):
                continue
            row = {"id": cgid, "symbol": sym, "name": name}
            if inc:
                plats = c.get("platforms")
                row["platforms"] = plats if isinstance(plats, dict) else {}
            out.append(row)
        return out
    except Exception as e:
        status = 500
        return _err("CONFLICT", "Internal error", detail=str(e))
    finally:
        _ = (start, status)

def API_coins_markets(vs_currency, ids=None, names=None, symbols=None, include_tokens=None, category=None, order=None, per_page=None, page=None, sparkline=None, price_change_percentage=None, locale=None, precision=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    status = 200
    try:
        if not isinstance(vs_currency, str) or not vs_currency.strip():
            status = 400
            return _err("VALIDATION_ERROR", "vs_currency is required and must be a non-empty string")
        vs = vs_currency.strip().lower()

        if ids is not None and not isinstance(ids, str):
            status = 400
            return _err("VALIDATION_ERROR", "ids must be a string when provided")
        if names is not None and not isinstance(names, str):
            status = 400
            return _err("VALIDATION_ERROR", "names must be a string when provided")
        if symbols is not None and not isinstance(symbols, str):
            status = 400
            return _err("VALIDATION_ERROR", "symbols must be a string when provided")
        if include_tokens is not None and include_tokens not in ("top", "all"):
            status = 400
            return _err("VALIDATION_ERROR", "include_tokens must be one of: top, all")
        if category is not None and not isinstance(category, str):
            status = 400
            return _err("VALIDATION_ERROR", "category must be a string when provided")
        allowed_order = {"market_cap_asc", "market_cap_desc", "volume_asc", "volume_desc", "id_asc", "id_desc"}
        if order is not None and order not in allowed_order:
            status = 400
            return _err("VALIDATION_ERROR", "order must be one of: market_cap_asc, market_cap_desc, volume_asc, volume_desc, id_asc, id_desc")
        if per_page is not None:
            if not isinstance(per_page, int):
                status = 400
                return _err("VALIDATION_ERROR", "per_page must be an integer when provided")
            if per_page < 1 or per_page > 250:
                status = 400
                return _err("VALIDATION_ERROR", "per_page must be between 1 and 250")
        if page is not None:
            if not isinstance(page, int):
                status = 400
                return _err("VALIDATION_ERROR", "page must be an integer when provided")
            if page < 1:
                status = 400
                return _err("VALIDATION_ERROR", "page must be >= 1")
        if sparkline is not None and not isinstance(sparkline, bool):
            status = 400
            return _err("VALIDATION_ERROR", "sparkline must be a boolean when provided")
        if locale is not None and locale not in {"ar","bg","cs","da","de","el","en","es","fi","fr","he","hi","hr","hu","id","it","ja","ko","lt","nl","no","pl","pt","ro","ru","sk","sl","sv","th","tr","uk","vi","zh","zh-tw"}:
            status = 400
            return _err("VALIDATION_ERROR", "locale is invalid")
        allowed_precision = {"full"} | {str(i) for i in range(0, 19)}
        if precision is not None and precision not in allowed_precision:
            status = 400
            return _err("VALIDATION_ERROR", "precision must be 'full' or an integer string between 0 and 18")

        ppg = per_page if per_page is not None else 100
        pg = page if page is not None else 1
        ordv = order if order is not None else "market_cap_desc"

        # price_change_percentage parsing
        tf_allowed = {"1h","24h","7d","14d","30d","200d","1y"}
        tfs = []
        if price_change_percentage is not None:
            if not isinstance(price_change_percentage, str):
                status = 400
                return _err("VALIDATION_ERROR", "price_change_percentage must be a string when provided")
            tfs = [x.strip() for x in price_change_percentage.split(",") if x.strip()]
            bad = [x for x in tfs if x not in tf_allowed]
            if bad:
                status = 400
                return _err("VALIDATION_ERROR", "price_change_percentage contains invalid values", invalid=bad)

        coins = _load("coins.json")
        cats = _load("coin_categories.json")
        snaps = _load("coin_market_snapshots.json")

        # category filter: provided category refers to coin_categories.category_id; coins.categories membership
        cat_id = None
        if category is not None and category.strip():
            cat_q = category.strip()
            for cr in cats if isinstance(cats, list) else []:
                if isinstance(cr, dict) and cr.get("category_id") == cat_q:
                    cat_id = cat_q
                    break
            if cat_id is None:
                # Unknown category: return empty list
                return []

        # Build indexes
        by_cgid = {}
        by_name = {}
        by_symbol = {}
        for c in coins if isinstance(coins, list) else []:
            if not isinstance(c, dict):
                continue
            cgid = c.get("coingecko_id")
            if isinstance(cgid, str):
                by_cgid[cgid.lower()] = c
            nm = c.get("name")
            if isinstance(nm, str):
                by_name.setdefault(nm.lower(), []).append(c)
            sym = c.get("symbol")
            if isinstance(sym, str):
                by_symbol.setdefault(sym.lower(), []).append(c)

        selector_kind = None
        selector_values = []
        if ids is not None and ids.strip():
            selector_kind = "ids"
            selector_values = [x.strip().lower() for x in ids.split(",") if x.strip()]
        elif names is not None and names.strip():
            selector_kind = "names"
            selector_values = [x.strip().lower() for x in names.split(",") if x.strip()]
        elif symbols is not None and symbols.strip():
            selector_kind = "symbols"
            selector_values = [x.strip().lower() for x in symbols.split(",") if x.strip()]

        selected = []
        if selector_kind is None:
            selected = [c for c in coins if isinstance(c, dict)]
        elif selector_kind == "ids":
            for v in selector_values:
                c = by_cgid.get(v)
                if c:
                    selected.append(c)
        elif selector_kind == "names":
            for v in selector_values:
                selected.extend(by_name.get(v, []))
        else:
            mode = include_tokens or "top"
            for v in selector_values:
                cands = by_symbol.get(v, [])
                if not cands:
                    continue
                if mode == "all":
                    selected.extend(cands)
                else:
                    # pick best by market_cap_rank in this vs currency
                    best = None
                    best_rank = None
                    for c in cands:
                        cid = c.get("id")
                        if not isinstance(cid, str):
                            continue
                        rank = None
                        for s in snaps if isinstance(snaps, list) else []:
                            if isinstance(s, dict) and s.get("coin_id") == cid and s.get("vs_currency") == vs:
                                r = s.get("market_cap_rank")
                                if isinstance(r, (int, float)) and not isinstance(r, bool):
                                    rank = r
                                    break
                        if rank is None:
                            continue
                        if best is None or (best_rank is None) or rank < best_rank:
                            best = c
                            best_rank = rank
                    selected.append(best if best is not None else cands[0])

        # Filter by category membership
        if cat_id is not None:
            filtered = []
            for c in selected:
                cats_list = c.get("categories")
                if isinstance(cats_list, list) and cat_id in cats_list:
                    filtered.append(c)
            selected = filtered

        # snapshot lookup for this vs currency
        snap_by_coin = {}
        for s in snaps if isinstance(snaps, list) else []:
            if not isinstance(s, dict):
                continue
            if s.get("vs_currency") != vs:
                continue
            coin_id = s.get("coin_id")
            if isinstance(coin_id, str):
                snap_by_coin[coin_id] = s

        def _parse_dt(x):
            if isinstance(x, str):
                try:
                    if x.endswith("Z"):
                        x = x[:-1] + "+00:00"
                    return datetime.datetime.fromisoformat(x)
                except Exception:
                    return None
            return None

        def _round_num(x):
            if not isinstance(x, (int, float)) or isinstance(x, bool):
                return x
            if precision is None or precision == "full":
                return float(x)
            return round(float(x), int(precision))

        want_spark = bool(sparkline)
        # Build rows
        rows = []
        for c in selected:
            if not isinstance(c, dict):
                continue
            cid = c.get("id")
            cgid = c.get("coingecko_id")
            sym = c.get("symbol")
            nm = c.get("name")
            if not isinstance(cid, str) or not isinstance(cgid, str) or not isinstance(sym, str) or not isinstance(nm, str):
                continue
            s = snap_by_coin.get(cid)
            if not s or not isinstance(s, dict) or s.get("status") == "error":
                continue
            cp = s.get("current_price")
            if not isinstance(cp, (int, float)) or isinstance(cp, bool) or cp < 0:
                continue

            row = {
                "id": cgid,
                "symbol": sym,
                "name": nm,
                "image": s.get("image_url"),
                "current_price": _round_num(cp),
                "market_cap": _round_num(s.get("market_cap")) if isinstance(s.get("market_cap"), (int, float)) and not isinstance(s.get("market_cap"), bool) else None,
                "market_cap_rank": s.get("market_cap_rank"),
                "fully_diluted_valuation": _round_num(s.get("fully_diluted_valuation")) if isinstance(s.get("fully_diluted_valuation"), (int, float)) and not isinstance(s.get("fully_diluted_valuation"), bool) else None,
                "total_volume": _round_num(s.get("total_volume")) if isinstance(s.get("total_volume"), (int, float)) and not isinstance(s.get("total_volume"), bool) else None,
                "high_24h": _round_num(s.get("high_24h")) if isinstance(s.get("high_24h"), (int, float)) and not isinstance(s.get("high_24h"), bool) else None,
                "low_24h": _round_num(s.get("low_24h")) if isinstance(s.get("low_24h"), (int, float)) and not isinstance(s.get("low_24h"), bool) else None,
                "price_change_24h": _round_num(s.get("price_change_24h")) if isinstance(s.get("price_change_24h"), (int, float)) and not isinstance(s.get("price_change_24h"), bool) else None,
                "price_change_percentage_24h": _round_num(s.get("price_change_percentage_24h")) if isinstance(s.get("price_change_percentage_24h"), (int, float)) and not isinstance(s.get("price_change_percentage_24h"), bool) else None,
                "market_cap_change_24h": _round_num(s.get("market_cap_change_24h")) if isinstance(s.get("market_cap_change_24h"), (int, float)) and not isinstance(s.get("market_cap_change_24h"), bool) else None,
                "market_cap_change_percentage_24h": _round_num(s.get("market_cap_change_percentage_24h")) if isinstance(s.get("market_cap_change_percentage_24h"), (int, float)) and not isinstance(s.get("market_cap_change_percentage_24h"), bool) else None,
                "circulating_supply": _round_num(s.get("circulating_supply")) if isinstance(s.get("circulating_supply"), (int, float)) and not isinstance(s.get("circulating_supply"), bool) else None,
                "total_supply": _round_num(s.get("total_supply")) if isinstance(s.get("total_supply"), (int, float)) and not isinstance(s.get("total_supply"), bool) else None,
                "max_supply": _round_num(s.get("max_supply")) if isinstance(s.get("max_supply"), (int, float)) and not isinstance(s.get("max_supply"), bool) else None,
                "ath": _round_num(s.get("ath")) if isinstance(s.get("ath"), (int, float)) and not isinstance(s.get("ath"), bool) else None,
                "ath_change_percentage": _round_num(s.get("ath_change_percentage")) if isinstance(s.get("ath_change_percentage"), (int, float)) and not isinstance(s.get("ath_change_percentage"), bool) else None,
                "ath_date": s.get("ath_date"),
                "atl": _round_num(s.get("atl")) if isinstance(s.get("atl"), (int, float)) and not isinstance(s.get("atl"), bool) else None,
                "atl_change_percentage": _round_num(s.get("atl_change_percentage")) if isinstance(s.get("atl_change_percentage"), (int, float)) and not isinstance(s.get("atl_change_percentage"), bool) else None,
                "atl_date": s.get("atl_date"),
                "roi": s.get("roi"),
                "last_updated": s.get("last_updated"),
            }

            # include selected price change % timeframes
            if "1h" in tfs:
                if isinstance(s.get("price_change_percentage_1h"), (int, float)) and not isinstance(s.get("price_change_percentage_1h"), bool):
                    row["price_change_percentage_1h"] = _round_num(s.get("price_change_percentage_1h"))
            # others are already standard fields in schema
            for tf, field in [("7d","price_change_percentage_7d"),("14d","price_change_percentage_14d"),("30d","price_change_percentage_30d"),("200d","price_change_percentage_200d"),("1y","price_change_percentage_1y")]:
                if tf in tfs:
                    val = s.get(field)
                    if isinstance(val, (int, float)) and not isinstance(val, bool):
                        row[field] = _round_num(val)

            if want_spark:
                sp = s.get("sparkline_7d_prices")
                if isinstance(sp, list):
                    row["sparkline_in_7d"] = {"price": [_round_num(x) for x in sp]}
                else:
                    row["sparkline_in_7d"] = {"price": []}

            rows.append(row)

        # Sorting
        def _num_or_none(x):
            return x if isinstance(x, (int, float)) and not isinstance(x, bool) else None

        reverse = ordv.endswith("_desc")
        if ordv.startswith("market_cap_"):
            rows.sort(key=lambda r: (_num_or_none(r.get("market_cap")) is None, _num_or_none(r.get("market_cap")) if _num_or_none(r.get("market_cap")) is not None else (float("inf") if not reverse else float("-inf"))), reverse=reverse)
        elif ordv.startswith("volume_"):
            rows.sort(key=lambda r: (_num_or_none(r.get("total_volume")) is None, _num_or_none(r.get("total_volume")) if _num_or_none(r.get("total_volume")) is not None else (float("inf") if not reverse else float("-inf"))), reverse=reverse)
        elif ordv == "id_asc":
            rows.sort(key=lambda r: (str(r.get("id") or "")).lower())
        elif ordv == "id_desc":
            rows.sort(key=lambda r: (str(r.get("id") or "")).lower(), reverse=True)

        # Pagination
        total = len(rows)
        start_i = (pg - 1) * ppg
        end_i = start_i + ppg
        if start_i >= total:
            return []
        return rows[start_i:end_i]
    except Exception as e:
        status = 500
        return _err("CONFLICT", "Internal error", detail=str(e))
    finally:
        _ = (start, status)

def API_coins_id(id, localization=None, tickers=None, market_data=None, community_data=None, developer_data=None, sparkline=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string")
    for bname, bval in [
        ("localization", localization),
        ("tickers", tickers),
        ("market_data", market_data),
        ("community_data", community_data),
        ("developer_data", developer_data),
        ("sparkline", sparkline),
    ]:
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be a boolean when provided")

    # Defaults per endpoint: localization/tickers/market_data/community_data/developer_data default true, sparkline default false
    inc_localization = True if localization is None else bool(localization)
    inc_tickers = True if tickers is None else bool(tickers)
    inc_market = True if market_data is None else bool(market_data)
    inc_comm = True if community_data is None else bool(community_data)
    inc_dev = True if developer_data is None else bool(developer_data)
    inc_spark = False if sparkline is None else bool(sparkline)

    coins = _load("coins.json")
    snaps = _load("coin_market_snapshots.json")
    if not isinstance(coins, list):
        coins = []
    if not isinstance(snaps, list):
        snaps = []

    coin = None
    cid_norm = id.strip()
    # Accept either coingecko_id or internal primary key (audit showed callers used internal id)
    for c in coins:
        if not isinstance(c, dict):
            continue
        if c.get("coingecko_id") == cid_norm or c.get("id") == cid_norm:
            coin = c
            break
    if coin is None:
        return _err("NOT_FOUND", "Coin not found", id=id)

    coin_pk = coin.get("id")
    # choose a representative snapshot for additional fields (prefer usd, else any)
    snap = None
    if isinstance(coin_pk, str) and coin_pk:
        for s in snaps:
            if isinstance(s, dict) and s.get("coin_id") == coin_pk and s.get("vs_currency") == "usd":
                snap = s
                break
        if snap is None:
            for s in snaps:
                if isinstance(s, dict) and s.get("coin_id") == coin_pk:
                    snap = s
                    break

    # Helper: parse dt-like to ISO
    def _iso(v):
        if v is None:
            return None
        if isinstance(v, str):
            return v
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            try:
                return datetime.datetime.fromtimestamp(v, tz=datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
            except Exception:
                return None
        if isinstance(v, datetime.datetime):
            d = v
            if d.tzinfo is None:
                d = d.replace(tzinfo=datetime.timezone.utc)
            return d.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    resp = {
        "id": coin.get("coingecko_id") or coin.get("id"),
        "symbol": coin.get("symbol"),
        "name": coin.get("name"),
        "web_slug": coin.get("web_slug"),
        "asset_platform_id": coin.get("asset_platform_id"),
        "platforms": coin.get("platforms") if isinstance(coin.get("platforms"), dict) else {},
        "detail_platforms": coin.get("detail_platforms") if isinstance(coin.get("detail_platforms"), dict) else {},
        "block_time_in_minutes": coin.get("block_time_in_minutes"),
        "hashing_algorithm": coin.get("hashing_algorithm"),
        "categories": coin.get("categories") if isinstance(coin.get("categories"), list) else [],
        "preview_listing": bool(coin.get("preview_listing")) if coin.get("preview_listing") is not None else False,
        "public_notice": coin.get("public_notice"),
        "additional_notices": coin.get("additional_notices") if isinstance(coin.get("additional_notices"), list) else [],
        "image": coin.get("image") if isinstance(coin.get("image"), dict) else {},
        "country_origin": coin.get("country_origin"),
        "genesis_date": _iso(coin.get("genesis_date")),
        "sentiment_votes_up_percentage": coin.get("sentiment_votes_up_percentage"),
        "sentiment_votes_down_percentage": coin.get("sentiment_votes_down_percentage"),
        "last_updated": _iso(coin.get("updated_at")),
    }

    if inc_localization:
        resp["localization"] = coin.get("localization") if isinstance(coin.get("localization"), dict) else {}
        resp["description"] = coin.get("description") if isinstance(coin.get("description"), dict) else {}
    else:
        # omit localization/description blobs
        pass

    # links blob is controlled by upstream flags in real API; not present here as separate flags, include if available
    resp["links"] = coin.get("links") if isinstance(coin.get("links"), dict) else {}

    if inc_tickers:
        resp["tickers"] = coin.get("tickers") if isinstance(coin.get("tickers"), list) else []
    if inc_comm:
        resp["community_data"] = coin.get("community_data") if isinstance(coin.get("community_data"), dict) else {}
    if inc_dev:
        resp["developer_data"] = coin.get("developer_data") if isinstance(coin.get("developer_data"), dict) else {}

    if inc_market:
        # Provide minimal market_data from snapshot if available; otherwise empty object
        md = coin.get("market_data") if isinstance(coin.get("market_data"), dict) else {}
        if not md and snap:
            vs = snap.get("vs_currency")
            if isinstance(vs, str) and vs:
                vs = vs.lower()
                md = {
                    "current_price": {vs: snap.get("current_price")} if isinstance(snap.get("current_price"), (int, float)) and not isinstance(snap.get("current_price"), bool) else {},
                    "market_cap": {vs: snap.get("market_cap")} if isinstance(snap.get("market_cap"), (int, float)) and not isinstance(snap.get("market_cap"), bool) else {},
                    "total_volume": {vs: snap.get("total_volume")} if isinstance(snap.get("total_volume"), (int, float)) and not isinstance(snap.get("total_volume"), bool) else {},
                    "market_cap_rank": snap.get("market_cap_rank"),
                    "price_change_24h": snap.get("price_change_24h"),
                    "price_change_percentage_24h": snap.get("price_change_percentage_24h"),
                    "market_cap_change_24h": snap.get("market_cap_change_24h"),
                    "market_cap_change_percentage_24h": snap.get("market_cap_change_percentage_24h"),
                    "circulating_supply": snap.get("circulating_supply"),
                    "total_supply": snap.get("total_supply"),
                    "max_supply": snap.get("max_supply"),
                    "ath": {vs: snap.get("ath")} if isinstance(snap.get("ath"), (int, float)) and not isinstance(snap.get("ath"), bool) else {},
                    "ath_change_percentage": {vs: snap.get("ath_change_percentage")} if isinstance(snap.get("ath_change_percentage"), (int, float)) and not isinstance(snap.get("ath_change_percentage"), bool) else {},
                    "ath_date": {vs: _iso(snap.get("ath_date"))} if snap.get("ath_date") is not None else {},
                    "atl": {vs: snap.get("atl")} if isinstance(snap.get("atl"), (int, float)) and not isinstance(snap.get("atl"), bool) else {},
                    "atl_change_percentage": {vs: snap.get("atl_change_percentage")} if isinstance(snap.get("atl_change_percentage"), (int, float)) and not isinstance(snap.get("atl_change_percentage"), bool) else {},
                    "atl_date": {vs: _iso(snap.get("atl_date"))} if snap.get("atl_date") is not None else {},
                    "last_updated": _iso(snap.get("last_updated")),
                }
        resp["market_data"] = md if isinstance(md, dict) else {}

    if inc_spark:
        # Sparkline uses coin_market_snapshots.sparkline_7d_prices when available
        spark_prices = None
        if snap and isinstance(snap.get("sparkline_7d_prices"), list):
            spark_prices = snap.get("sparkline_7d_prices")
        if spark_prices is None:
            # try any snapshot containing sparkline
            if isinstance(coin_pk, str) and coin_pk:
                for s in snaps:
                    if isinstance(s, dict) and s.get("coin_id") == coin_pk and isinstance(s.get("sparkline_7d_prices"), list):
                        spark_prices = s.get("sparkline_7d_prices")
                        break
        resp["sparkline_in_7d"] = {"price": spark_prices or []}

    return {
        "data": resp,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def API_coins_id_ohlc(id, vs_currency, days, precision=None, **_extra):
    import json, os, datetime, time, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Input validation
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if not isinstance(vs_currency, str) or not vs_currency.strip():
        return _err("VALIDATION_ERROR", "vs_currency must be a non-empty string")
    if not isinstance(days, str) or not days.strip():
        return _err("VALIDATION_ERROR", "days must be a string")
    allowed_days = {"1", "7", "14", "30", "90", "180", "365"}
    if days not in allowed_days:
        return _err("VALIDATION_ERROR", "days must be one of the allowed values", allowed=list(sorted(allowed_days)))
    allowed_prec = {"full"} | {str(i) for i in range(0, 19)}
    if precision is not None and (not isinstance(precision, str) or precision not in allowed_prec):
        return _err("VALIDATION_ERROR", "precision must be 'full' or an integer string 0..18")

    vs = vs_currency.strip().lower()

    coins = _load("coins.json")
    ohlc_rows = _load("coin_ohlc.json")
    if not isinstance(coins, list):
        coins = []
    if not isinstance(ohlc_rows, list):
        ohlc_rows = []

    cid_norm = id.strip()
    coin = None
    # Accept either coingecko_id or internal id
    for c in coins:
        if not isinstance(c, dict):
            continue
        if c.get("coingecko_id") == cid_norm or c.get("id") == cid_norm:
            coin = c
            break
    if not coin:
        return _err("NOT_FOUND", "coin not found", id=id)

    coin_pk = coin.get("id")
    if not isinstance(coin_pk, str) or not coin_pk:
        return _err("CONFLICT", "coin row missing internal id", id=id)

    row = None
    for r in ohlc_rows:
        if not isinstance(r, dict):
            continue
        if r.get("coin_id") == coin_pk and isinstance(r.get("vs_currency"), str) and r.get("vs_currency").lower() == vs and r.get("days") == days:
            row = r
            break

    if row is None:
        # Real API would likely fetch/compute; offline cache returns NOT_FOUND
        return _err("NOT_FOUND", "ohlc data not found", id=id, vs_currency=vs, days=days)

    candles = row.get("candles")
    if not isinstance(candles, list):
        return _err("CONFLICT", "stored ohlc row malformed (candles not array)", row_id=row.get("id"))

    # Precision rounding applies to numeric quote-currency values (open/high/low/close)
    def _round(v):
        if v is None or not isinstance(v, (int, float)) or isinstance(v, bool):
            return v
        if precision is None or precision == "full":
            return float(v)
        try:
            p = int(precision)
        except Exception:
            return float(v)
        return round(float(v), p)

    out = []
    for c in candles:
        if not (isinstance(c, list) and len(c) >= 5):
            continue
        ts = c[0]
        o = _round(c[1])
        h = _round(c[2])
        l = _round(c[3])
        cl = _round(c[4])
        # keep timestamp as-is
        if isinstance(ts, (int, float)) and not isinstance(ts, bool):
            ts = int(ts)
        out.append([ts, o, h, l, cl])

    return {
        "data": out,
        "meta": {
            "coin_id": coin.get("coingecko_id") or coin.get("id"),
            "vs_currency": vs,
            "days": days,
            "status": row.get("status"),
            "last_updated": row.get("last_updated"),
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def API_search_data(query, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, random

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    q_raw = query
    q_norm = query.strip().lower()

    coins = _load("coins.json")
    cats = _load("coin_categories.json")
    searches = _load("search_queries.json")
    snapshots = _load("coin_market_snapshots.json")

    # Build quick map for market_cap_rank and images for coin search results
    best_snap_by_coin = {}
    for s in snapshots:
        if not isinstance(s, dict):
            continue
        cid = s.get("coin_id")
        if not cid:
            continue
        # choose any snapshot with a rank; prefer lower rank number; else first
        cur = best_snap_by_coin.get(cid)
        rank = s.get("market_cap_rank")
        try:
            rank_val = float(rank) if rank is not None else None
        except Exception:
            rank_val = None
        if cur is None:
            best_snap_by_coin[cid] = s
        else:
            try:
                cur_rank = cur.get("market_cap_rank")
                cur_rank_val = float(cur_rank) if cur_rank is not None else None
            except Exception:
                cur_rank_val = None
            if cur_rank_val is None and rank_val is not None:
                best_snap_by_coin[cid] = s
            elif cur_rank_val is not None and rank_val is not None and rank_val < cur_rank_val:
                best_snap_by_coin[cid] = s

    def _coin_thumb_large(coin_row):
        img = coin_row.get("image") if isinstance(coin_row, dict) else None
        if isinstance(img, dict):
            thumb = img.get("thumb")
            large = img.get("large") or img.get("small")
            if thumb or large:
                return thumb, large
        # fallback to snapshot image_url
        snap = best_snap_by_coin.get(coin_row.get("id"))
        if isinstance(snap, dict):
            url = snap.get("image_url")
            return url, url
        return None, None

    # Search logic: indexed lookups over coingecko_id/symbol/name; and category name/category_id
    # Simple substring match, prioritize startswith then contains.
    def _score(text):
        if not text:
            return None
        t = str(text).lower()
        if t == q_norm:
            return 0
        if t.startswith(q_norm):
            return 1
        if q_norm in t:
            return 2
        return None

    coin_hits = []
    for c in coins:
        if not isinstance(c, dict):
            continue
        # include even inactive/delisted? CoinGecko search includes; we'll include all but keep ordering.
        s1 = _score(c.get("coingecko_id"))
        s2 = _score(c.get("symbol"))
        s3 = _score(c.get("name"))
        s = min([x for x in [s1, s2, s3] if x is not None], default=None)
        if s is None:
            continue
        snap = best_snap_by_coin.get(c.get("id"), {})
        rank = snap.get("market_cap_rank")
        try:
            rank_key = float(rank) if rank is not None else 1e18
        except Exception:
            rank_key = 1e18
        thumb, large = _coin_thumb_large(c)
        coin_hits.append((s, rank_key, c, thumb, large))

    coin_hits.sort(key=lambda x: (x[0], x[1], str((x[2] or {}).get("coingecko_id") or "")))
    coins_out = []
    for _, _, c, thumb, large in coin_hits[:50]:
        snap = best_snap_by_coin.get(c.get("id"), {})
        coins_out.append({
            "id": c.get("coingecko_id"),
            "name": c.get("name"),
            "api_symbol": c.get("symbol"),
            "symbol": c.get("symbol"),
            "market_cap_rank": snap.get("market_cap_rank"),
            "thumb": thumb,
            "large": large,
        })

    cat_hits = []
    for cat in cats:
        if not isinstance(cat, dict):
            continue
        if cat.get("status") not in ("active", "deprecated"):
            continue
        s1 = _score(cat.get("name"))
        s2 = _score(cat.get("category_id"))
        s = min([x for x in [s1, s2] if x is not None], default=None)
        if s is None:
            continue
        cat_hits.append((s, str(cat.get("category_id") or ""), cat))
    cat_hits.sort(key=lambda x: (x[0], x[1]))
    categories_out = [{"id": c.get("category_id"), "name": c.get("name")} for _, _, c in cat_hits[:50]]

    # No exchanges/nfts dataset in this service cache; return empty arrays but well-formed.
    resp = {
        "coins": coins_out,
        "exchanges": [],
        "icos": [],
        "categories": categories_out,
        "nfts": [],
    }

    # Record request in search_queries (business rule)
    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    qid = f"sq_{int(now.timestamp()*1000)}_{random.randint(1000,9999)}"
    row = {
        "id": qid,
        "query": q_raw,
        "normalized_query": q_norm,
        "ip_hash": None,
        "user_agent_hash": None,
        "result_coins": coins_out,
        "result_exchanges": [],
        "result_categories": categories_out,
        "result_nfts": [],
        "result_icos": [],
        "status": "completed",
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    # Enforce caps in constraints (<=50 already). Save.
    searches.append(row)
    _save("search_queries.json", searches)

    latency_ms = int((time.perf_counter() - t0) * 1000)
    return {"data": resp, "meta": {"query": q_raw, "normalized_query": q_norm, "latency_ms": latency_ms}}

def API_trending_search(window=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time
    t0 = time.perf_counter()

    if window is None:
        window = "24h"
    if not isinstance(window, str):
        return _err("VALIDATION_ERROR", "window must be a string")
    allowed = {"1h", "24h", "7d"}
    if window not in allowed:
        return _err("VALIDATION_ERROR", "window must be one of the allowed values", allowed=list(sorted(allowed)))

    rows = _load("trending_snapshots.json")

    def _dtparse(x):
        if x is None:
            return None
        if isinstance(x, (int, float)):
            try:
                return datetime.datetime.fromtimestamp(float(x), tz=datetime.timezone.utc)
            except Exception:
                return None
        if isinstance(x, str):
            s = x.strip()
            if not s:
                return None
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    best = None
    best_ts = None
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("status") != "active":
            continue
        if r.get("window") != window:
            continue
        ts = _dtparse(r.get("computed_at")) or _dtparse(r.get("updated_at")) or _dtparse(r.get("created_at"))
        if best is None or (ts is not None and (best_ts is None or ts > best_ts)):
            best = r
            best_ts = ts

    if best is None:
        resp = {"coins": [], "nfts": [], "categories": []}
        latency_ms = int((time.perf_counter() - t0) * 1000)
        return {"data": resp, "meta": {"window": window, "computed_at": None, "latency_ms": latency_ms}}

    coins = best.get("coins")
    nfts = best.get("nfts")
    categories = best.get("categories")
    if not isinstance(coins, list): coins = []
    if not isinstance(nfts, list): nfts = []
    if not isinstance(categories, list): categories = []

    # Respect stored constraint caps (<=50), avoid fabricating beyond.
    resp = {"coins": coins[:50], "nfts": nfts[:50], "categories": categories[:50]}
    latency_ms = int((time.perf_counter() - t0) * 1000)
    return {"data": resp, "meta": {"window": window, "computed_at": best.get("computed_at"), "latency_ms": latency_ms}}

