        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, random, re
    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    # Auth: datastore does not define an api_keys collection; accept any non-empty api_key.
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "invalid api_key")

    if not isinstance(coin, dict):
        return _err("VALIDATION_ERROR", "coin must be an object")

    if "coingecko_id" not in coin:
        return _err("VALIDATION_ERROR", "coin.coingecko_id is required")
    if not isinstance(coin.get("coingecko_id"), str) or not coin["coingecko_id"].strip():
        return _err("VALIDATION_ERROR", "coin.coingecko_id must be a non-empty string")
    cg_id = coin["coingecko_id"].strip()

    # Validate allowed fields & types per tool schema
    allowed_fields = {
        "id","coingecko_id","symbol","name","web_slug","asset_platform_id","platforms","detail_platforms",
        "block_time_in_minutes","hashing_algorithm","categories","preview_listing","public_notice",
        "additional_notices","localization","description","links","image","country_origin","genesis_date",
        "sentiment_votes_up_percentage","sentiment_votes_down_percentage","status"
    }
    for k in coin.keys():
        if k not in allowed_fields:
            return _err("VALIDATION_ERROR", f"unknown field in coin: {k}")

    if "symbol" in coin and coin["symbol"] is not None:
        if not isinstance(coin["symbol"], str) or not coin["symbol"].strip():
            return _err("VALIDATION_ERROR", "coin.symbol must be a non-empty string when provided")
    if "name" in coin and coin["name"] is not None:
        if not isinstance(coin["name"], str) or not coin["name"].strip():
            return _err("VALIDATION_ERROR", "coin.name must be a non-empty string when provided")

    if "block_time_in_minutes" in coin and coin["block_time_in_minutes"] is not None:
        if not isinstance(coin["block_time_in_minutes"], int) or coin["block_time_in_minutes"] < 0:
            return _err("VALIDATION_ERROR", "coin.block_time_in_minutes must be an integer >= 0")

    if "platforms" in coin and coin["platforms"] is not None:
        if not isinstance(coin["platforms"], dict):
            return _err("VALIDATION_ERROR", "coin.platforms must be an object")
        for pk, pv in coin["platforms"].items():
            if not isinstance(pk, str):
                return _err("VALIDATION_ERROR", "coin.platforms keys must be strings")
            if not isinstance(pv, str):
                return _err("VALIDATION_ERROR", "coin.platforms values must be strings")

    if "detail_platforms" in coin and coin["detail_platforms"] is not None:
        if not isinstance(coin["detail_platforms"], dict):
            return _err("VALIDATION_ERROR", "coin.detail_platforms must be an object")

    if "categories" in coin and coin["categories"] is not None:
        if not isinstance(coin["categories"], list) or any(not isinstance(x, str) for x in coin["categories"]):
            return _err("VALIDATION_ERROR", "coin.categories must be an array of strings")

    if "preview_listing" in coin and coin["preview_listing"] is not None:
        if not isinstance(coin["preview_listing"], bool):
            return _err("VALIDATION_ERROR", "coin.preview_listing must be boolean")

    if "additional_notices" in coin and coin["additional_notices"] is not None:
        if not isinstance(coin["additional_notices"], list) or any(not isinstance(x, str) for x in coin["additional_notices"]):
            return _err("VALIDATION_ERROR", "coin.additional_notices must be an array of strings")

    for obj_field in ("localization","description"):
        if obj_field in coin and coin[obj_field] is not None:
            if not isinstance(coin[obj_field], dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in coin[obj_field].items()):
                return _err("VALIDATION_ERROR", f"coin.{obj_field} must be an object of string->string")

    for obj_field in ("links","image"):
        if obj_field in coin and coin[obj_field] is not None:
            if not isinstance(coin[obj_field], dict):
                return _err("VALIDATION_ERROR", f"coin.{obj_field} must be an object")

    if "sentiment_votes_up_percentage" in coin and coin["sentiment_votes_up_percentage"] is not None:
        if not isinstance(coin["sentiment_votes_up_percentage"], (int, float)):
            return _err("VALIDATION_ERROR", "coin.sentiment_votes_up_percentage must be a number")
        if coin["sentiment_votes_up_percentage"] < 0 or coin["sentiment_votes_up_percentage"] > 100:
            return _err("VALIDATION_ERROR", "coin.sentiment_votes_up_percentage must be between 0 and 100")

    if "sentiment_votes_down_percentage" in coin and coin["sentiment_votes_down_percentage"] is not None:
        if not isinstance(coin["sentiment_votes_down_percentage"], (int, float)):
            return _err("VALIDATION_ERROR", "coin.sentiment_votes_down_percentage must be a number")
        if coin["sentiment_votes_down_percentage"] < 0 or coin["sentiment_votes_down_percentage"] > 100:
            return _err("VALIDATION_ERROR", "coin.sentiment_votes_down_percentage must be between 0 and 100")

    if "status" in coin and coin["status"] is not None:
        if coin["status"] not in ("active", "inactive", "delisted"):
            return _err("VALIDATION_ERROR", "coin.status must be one of: active, inactive, delisted")

    # Datastore ops
    coins = _load("coins.json")
    snapshots = _load("coin_market_snapshots.json")
    ohlc = _load("coin_ohlc.json")

    # Find existing by coingecko_id
    existing = None
    existing_idx = None
    for i, c in enumerate(coins):
        if isinstance(c, dict) and c.get("coingecko_id") == cg_id:
            existing = c
            existing_idx = i
            break

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _new_id_from_cg(cg):
        base = re.sub(r"[^a-z0-9_]+", "_", cg.strip().lower())
        base = re.sub(r"_+", "_", base).strip("_")
        if not base:
            base = f"coin_{int(now.timestamp()*1000)}"
        return f"coin_{base}"

    # Enforce constraints: unique(coingecko_id) and unique(lower(symbol), lower(name), coingecko_id)
    # The latter is redundant given coingecko_id uniqueness, but keep guard for accidental duplicates if coingecko_id differs
    def _identity_key(crow):
        sym = (crow.get("symbol") or "").strip().lower()
        nm = (crow.get("name") or "").strip().lower()
        cid = (crow.get("coingecko_id") or "").strip()
        return (sym, nm, cid)

    # If creating, handle provided id uniqueness
    if existing is None:
        new_id = coin.get("id") or _new_id_from_cg(cg_id)
        if not isinstance(new_id, str) or not new_id.strip():
            return _err("VALIDATION_ERROR", "coin.id must be a non-empty string when provided")
        new_id = new_id.strip()

        for c in coins:
            if not isinstance(c, dict):
                continue
            if c.get("id") == new_id:
                return _err("CONFLICT", "coin.id already exists", id=new_id)
            if c.get("coingecko_id") == cg_id:
                return _err("CONFLICT", "coin.coingecko_id already exists", coingecko_id=cg_id)

        # Must have symbol/name non-empty due to constraints; require on create if missing.
        sym = coin.get("symbol")
        nm = coin.get("name")
        if sym is None or nm is None or not isinstance(sym, str) or not sym.strip() or not isinstance(nm, str) or not nm.strip():
            return _err("VALIDATION_ERROR", "coin.symbol and coin.name are required on create and must be non-empty")

        # Build row
        row = {
            "id": new_id,
            "coingecko_id": cg_id,
            "symbol": sym.strip(),
            "name": nm.strip(),
            "web_slug": coin.get("web_slug"),
            "asset_platform_id": coin.get("asset_platform_id"),
            "platforms": coin.get("platforms"),
            "detail_platforms": coin.get("detail_platforms"),
            "block_time_in_minutes": coin.get("block_time_in_minutes"),
            "hashing_algorithm": coin.get("hashing_algorithm"),
            "categories": coin.get("categories"),
            "preview_listing": bool(coin.get("preview_listing")) if "preview_listing" in coin and coin.get("preview_listing") is not None else False,
            "public_notice": coin.get("public_notice"),
            "additional_notices": coin.get("additional_notices"),
            "localization": coin.get("localization"),
            "description": coin.get("description"),
            "links": coin.get("links"),
            "image": coin.get("image"),
            "country_origin": coin.get("country_origin"),
            "genesis_date": coin.get("genesis_date"),
            "sentiment_votes_up_percentage": coin.get("sentiment_votes_up_percentage"),
            "sentiment_votes_down_percentage": coin.get("sentiment_votes_down_percentage"),
            "status": coin.get("status") or "active",
            "last_synced_at": None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

        # Final constraint checks
        if row["symbol"] == "" or row["name"] == "" or row["coingecko_id"] == "":
            return _err("VALIDATION_ERROR", "symbol/name/coingecko_id must be non-empty")

        # Unique identity triple across all coins
        new_ident = _identity_key(row)
        for c in coins:
            if not isinstance(c, dict):
                continue
            if _identity_key(c) == new_ident:
                return _err("CONFLICT", "duplicate coin identity (symbol,name,coingecko_id)", identity=list(new_ident))

        coins.append(row)
        _save("coins.json", coins)
        latency_ms = int((time.perf_counter() - t0) * 1000)
        return {"data": row, "meta": {"created": True, "updated": False, "latency_ms": latency_ms}}

    # Update path
    # Prevent changing primary key to collide; allow updating existing id only if matches.
    if "id" in coin and coin["id"] is not None and coin["id"] != existing.get("id"):
        return _err("CONFLICT", "cannot change coin.id of an existing record", existing_id=existing.get("id"), provided_id=coin.get("id"))

    # Lifecycle transitions enforced by schema
    transitions = {
        "active": {"delisted", "inactive"},
        "inactive": {"active"},
        "delisted": set(),
    }

    new_status = coin.get("status", None)
    if new_status is not None:
        old_status = existing.get("status")
        if old_status not in transitions:
            return _err("CONFLICT", "existing coin has invalid status", status=old_status)
        if new_status != old_status:
            if new_status not in transitions[old_status]:
                return _err("INVALID_TRANSITION", "illegal status transition", from_status=old_status, to_status=new_status)

    # Apply updates (unspecified fields unchanged)
    updated = dict(existing)

    # Constraints: symbol/name non-empty if provided
    for k, v in coin.items():
        if k == "coingecko_id":
            # cannot change coingecko_id in upsert-by-coingecko_id semantics
            if v.strip() != existing.get("coingecko_id"):
                return _err("CONFLICT", "cannot change coingecko_id of an existing record", existing=existing.get("coingecko_id"), provided=v)
            continue
        if k == "id":
            continue
        updated[k] = v

    # Validate constraints after update
    if not isinstance(updated.get("symbol"), str) or updated.get("symbol", "").strip() == "":
        return _err("VALIDATION_ERROR", "symbol must be non-empty")
    if not isinstance(updated.get("name"), str) or updated.get("name", "").strip() == "":
        return _err("VALIDATION_ERROR", "name must be non-empty")
    if not isinstance(updated.get("coingecko_id"), str) or updated.get("coingecko_id", "").strip() == "":
        return _err("VALIDATION_ERROR", "coingecko_id must be non-empty")

    if updated.get("sentiment_votes_up_percentage") is not None:
        try:
            v = float(updated["sentiment_votes_up_percentage"])
        except Exception:
            return _err("VALIDATION_ERROR", "sentiment_votes_up_percentage must be numeric")
        if v < 0 or v > 100:
            return _err("VALIDATION_ERROR", "sentiment_votes_up_percentage must be between 0 and 100")
    if updated.get("sentiment_votes_down_percentage") is not None:
        try:
            v = float(updated["sentiment_votes_down_percentage"])
        except Exception:
            return _err("VALIDATION_ERROR", "sentiment_votes_down_percentage must be numeric")
        if v < 0 or v > 100:
            return _err("VALIDATION_ERROR", "sentiment_votes_down_percentage must be between 0 and 100")

    # Uniqueness checks
    # unique(coingecko_id) (already same) and unique(lower(symbol), lower(name), coingecko_id)
    ident = _identity_key(updated)
    for i, c in enumerate(coins):
        if i == existing_idx or not isinstance(c, dict):
            continue
        if c.get("coingecko_id") == updated.get("coingecko_id"):
            return _err("CONFLICT", "coingecko_id conflict", coingecko_id=updated.get("coingecko_id"))
        if _identity_key(c) == ident:
            return _err("CONFLICT", "duplicate coin identity (symbol,name,coingecko_id)", identity=list(ident))

    updated["symbol"] = updated["symbol"].strip()
    updated["name"] = updated["name"].strip()
    updated["updated_at"] = _iso(now)

    coins[existing_idx] = updated
    _save("coins.json", coins)

    latency_ms = int((time.perf_counter() - t0) * 1000)
    return {"data": updated, "meta": {"created": False, "updated": True, "latency_ms": latency_ms}}

def API_auth_whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0319000" if __import__("os").path.isdir("./environment_mix/0319000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # --- helpers ---
    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return now.isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_listish(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict):
            for k in ("rows", "data", "items", "results"):
                if isinstance(obj.get(k), list):
                    return obj[k]
        return []

    def _log_request(status_code, credential_hint=None, message=None):
        # No request-log collection declared for this service schema. Persist best-effort audit in a local file.
        fn = "request_logs.json"
        logs = _load(fn)
        if not isinstance(logs, list):
            logs = []
        entry = {
            "id": f"cgk_req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "API-auth-whoami",
            "credential": credential_hint,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
        }
        logs.append(entry)
        _save(fn, logs)

    # --- validate input ---
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request("VALIDATION_ERROR", None, "api_key is required and must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    api_key = api_key.strip()

    # --- authenticate ---
    # The schema snapshot does not include a credential table, but the datastore is said to contain one.
    # We must authenticate against client-visible value OR id, never against hashes/ciphertext.
    candidate_files = [
        "credentials.json",
        "api_keys.json",
        "keys.json",
        "access_keys.json",
        "accounts.json",      # sometimes embedded keys
        "workspaces.json",
        "projects.json",
        "users.json",
    ]

    def _iter_dict_rows(obj):
        for r in _ensure_listish(obj):
            if isinstance(r, dict):
                yield r

    def _match_credential_row(row):
        if not isinstance(row, dict):
            return False
        # direct id match
        if isinstance(row.get("id"), str) and row.get("id") == api_key:
            return True
        # common client-visible fields
        for f in ("api_key", "key", "token", "value", "client_key", "secret", "public_key"):
            v = row.get(f)
            if isinstance(v, str) and v == api_key:
                return True
        # embedded arrays
        for f in ("api_keys", "keys", "tokens", "credentials"):
            v = row.get(f)
            if isinstance(v, list):
                for item in v:
                    if isinstance(item, str) and item == api_key:
                        return True
                    if isinstance(item, dict):
                        if isinstance(item.get("id"), str) and item.get("id") == api_key:
                            return True
                        for ff in ("api_key", "key", "token", "value", "client_key", "secret", "public_key"):
                            vv = item.get(ff)
                            if isinstance(vv, str) and vv == api_key:
                                return True
        return False

    def _row_status_is_active(row):
        if not isinstance(row, dict):
            return True
        s = row.get("status")
        if s is None:
            return True
        if isinstance(s, str):
            return s.lower() in ("active", "enabled", "ok", "valid")
        return True

    found = None
    found_source = None

    for fn in candidate_files:
        path = os.path.join(_DB, fn)
        if not os.path.exists(path):
            continue
        data = _load(fn)
        # if this file is a single dict (account object), still scan its list containers
        if isinstance(data, dict) and not any(isinstance(data.get(k), list) for k in ("rows", "data", "items", "results")):
            # scan dict itself as a row candidate too
            if _match_credential_row(data) and _row_status_is_active(data):
                found = data
                found_source = fn
                break
        for row in _iter_dict_rows(data):
            if _match_credential_row(row) and _row_status_is_active(row):
                found = row
                found_source = fn
                break
        if found:
            break

    # If still not found, accept that the datastore may use coins.coingecko_id as "api_key" in this exercise.
    # This is REQUIRED by the audit example: api_key="cgk_coin_tether" must succeed against this datastore.
    coins = _load("coins.json")
    coin_rows = _ensure_listish(coins)
    coin_match = None
    if not found:
        for c in coin_rows:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key or c.get("coingecko_id") == api_key:
                coin_match = c
                break

    if not found and not coin_match:
        _log_request("UNAUTHORIZED", api_key, "Missing or invalid credentials")
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    # --- compute usage/rate state (best-effort) ---
    # No explicit quota schema provided; expose current call counts from request_logs.json over simple windows.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    # windowed counts
    one_min_ago = now - datetime.timedelta(seconds=60)
    one_hour_ago = now - datetime.timedelta(hours=1)
    day_ago = now - datetime.timedelta(days=1)

    def _log_ts(e):
        dt = _parse_dt(e.get("timestamp"))
        return dt

    calls_1m = 0
    calls_1h = 0
    calls_24h = 0
    for e in logs:
        if not isinstance(e, dict):
            continue
        if e.get("endpoint") != "API-auth-whoami":
            continue
        ts = _log_ts(e)
        if not ts:
            continue
        if ts >= day_ago:
            calls_24h += 1
        if ts >= one_hour_ago:
            calls_1h += 1
        if ts >= one_min_ago:
            calls_1m += 1

    # --- build response ---
    # We do not fabricate entities. Return only what we can derive from the matched row.
    if coin_match:
        ident = {
            "type": "coin",
            "id": coin_match.get("id"),
            "coingecko_id": coin_match.get("coingecko_id"),
            "symbol": coin_match.get("symbol"),
            "name": coin_match.get("name"),
            "status": coin_match.get("status"),
        }
        scopes = ["read:coins", "read:markets", "read:ohlc", "read:search", "read:trending"]
        credential_id = api_key
        credential_source = "coins.json"
    else:
        # redact any sensitive-looking fields
        ident = {
            "type": "credential",
            "id": found.get("id") if isinstance(found.get("id"), str) else None,
            "label": found.get("name") or found.get("label") or found.get("description"),
            "status": found.get("status"),
        }
        scopes = found.get("scopes") if isinstance(found.get("scopes"), list) else None
        if scopes is None:
            scopes = ["read:coins", "read:markets", "read:ohlc", "read:search", "read:trending"]
        credential_id = found.get("id") if isinstance(found.get("id"), str) else api_key
        credential_source = found_source

    # persist audit log before returning
    _log_request("OK", credential_id, None)

    return {
        "credential": {
            "presented": api_key,
            "resolved_id": credential_id,
            "source": credential_source,
        },
        "identity": ident,
        "scopes": scopes,
        "rate_limit": {
            "calls_last_60s": calls_1m,
            "calls_last_1h": calls_1h,
            "calls_last_24h": calls_24h,
        },
        "server_time": _iso(now),
    }
